(function(){const A=[{"id":"sp10-opros-groma","n":"Опрос Грома","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Маленький колокольчик.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы обращаетесь к стихии: вопрошаете эхо этого места (оно повторяет слова, звучавшие здесь за последние сутки). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-shag-ineya","n":"Шаг Инея","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 холод","cl":["Друид","Следопыт","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (холод). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-vlast-plameni","n":"Власть Пламени","l":8,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 огонь","cl":["Чародей","Колдун"],"ds":"Вы повелеваете стихией (пламени) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Ловкость), 6к10 урона (огонь) при провале и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение, половина при успехе.","save":"Ловкость","atk":false,"mech":"Власть","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-perenos-kostey","n":"Перенос Костей","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по костяной тропе на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-balzam-pustoty","n":"Бальзам Пустоты","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «силовое поле» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-slovo-zvezd","n":"Слово Звёзд","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 излучение","cl":["Бард","Жрец"],"ds":"Вы произносите истинное слово (звёзд). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (излучение) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-oblik-razuma","n":"Облик Разума","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Вы принимаете облик (разума): сопротивление урону «психический» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (психический). Попадание: цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-cep-yada","n":"Цепь Яда","l":2,"sc":"Преобразование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (яд) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-iskra-voln","n":"Искра Волн","l":0,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 дробящий","cl":["Жрец","Чародей","Друид"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (дробящий). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-voyuschaya-stena-vetra","n":"Воющая Стена Ветра","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 звук","cl":["Следопыт","Чародей","Друид"],"ds":"Стена (ветра) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Сила): 5к8 урона (звук) при провале (и цель отталкивается на 4,5 м в выбранном вами направлении), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Стена","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-oruzhie-kamnya","n":"Оружие Камня","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 дробящий","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (дробящий). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Сила): при провале она сбивается с ног, если она Большая или меньше. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-vspyshka-duhov","n":"Вспышка Духов","l":0,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 психический","cl":["Жрец","Бард","Колдун"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Мудрость), получая 1к6 урона (психический) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Мудрость","atk":false,"mech":"Вспышка","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-proklyatie-mirazhey","n":"Проклятие Миражей","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (психический), а в начале каждого её хода она бросает к4: на 1 она видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-slepok-sveta","n":"Слепок Света","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Святой символ.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Бард"],"ds":"Вы создаёте немагический предмет из застывшего света, яркого как свеча размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-maloe-chudo-shipov","n":"Малое Чудо Шипов","l":0,"sc":"Преобразование","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы творите мелкое чудо: заставить цветок распуститься, траву расти или ветку согнуться на 1 минуту. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-legion-run","n":"Легион Рун","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Жрец","Следопыт","Волшебник"],"ds":"Появляются четыре духа (рун): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «силовое поле». Каждый атакует заклинанием 1,5 м на 2к6 урона (силовое поле). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-pechat-vremeni","n":"Печать Времени","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Песчинка из песочных часов.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 силовое поле","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Мудрость): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Печать","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-kope-teni","n":"Копьё Тени","l":1,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 некротика","cl":["Колдун","Чародей","Бард"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (некротика). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-dvoynik-krovi","n":"Двойник Крови","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 некротика","cl":["Колдун","Жрец","Бард"],"ds":"Вы создаёте двойника из застывшей крови, твёрдой как рог. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (некротика) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-potok-molniy","n":"Поток Молний","l":3,"sc":"Воплощение","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 электричество","cl":["Чародей","Изобретатель","Друид"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Ловкость): 7к6 урона (электричество) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Поток","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-uzy-groma","n":"Узы Грома","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 звук","cl":["Бард","Чародей","Жрец"],"ds":"Узы (грома) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (звук) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-raspad-ineya","n":"Распад Инея","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кристалл льда.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 холод","cl":["Чародей","Друид"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (холод) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-duh-plameni","n":"Дух Пламени","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 огонь","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете духа (пламени) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (огонь). Иммунитет к урону «огонь». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-pokrov-kostey","n":"Покров Костей","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Фаланга пальца.","d":"1 час","conc":false,"rit":false,"dmg":"5 колющий","cl":["Жрец","Волшебник","Паладин"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (колющий); у вас сопротивление урону «колющий». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-kolco-pustoty","n":"Кольцо Пустоты","l":6,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 силовое поле","cl":["Чародей","Колдун"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Харизма): при провале оно получает 6к8 урона (силовое поле), не проходит и не может телепортироваться и перемещаться между планами до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Харизма","atk":false,"mech":"Кольцо","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-ubezhische-zvezd","n":"Убежище Звёзд","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: шатёр звёздного неба: каждый спящий получает вещий сон. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-chute-razuma","n":"Чутьё Разума","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы чувствуете разумных существ и их поверхностные эмоции в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-katastrofa-yada","n":"Катастрофа Яда","l":7,"sc":"Преобразование","t":"1 действие","r":"300 м","c":"ВСМ","m":"Жало пчелы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 яд","cl":["Колдун","Друид"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Телосложение) — 12к6 урона (яд) при провале (и цель отравлена до конца своего следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Телосложение","atk":false,"mech":"Катастрофа","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-opros-voln","n":"Опрос Волн","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Жрец","Друид","Паладин"],"ds":"Вы обращаетесь к стихии: вопрошаете водоём (вода помнит всё, что в неё упало). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-shag-vetra","n":"Шаг Ветра","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 звук","cl":["Следопыт","Друид","Бард"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Сила) или получает 1к6 урона (звук). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Шаг","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-vlast-kamnya","n":"Власть Камня","l":8,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 дробящий","cl":["Друид","Волшебник"],"ds":"Вы повелеваете стихией (камня) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Сила), 6к10 урона (дробящий) при провале и цель сбивается с ног, если она Большая или меньше, половина при успехе.","save":"Сила","atk":false,"mech":"Власть","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-burya-duhov","n":"Буря Духов","l":4,"sc":"Вызов","t":"1 действие","r":"90 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 психический","cl":["Бард","Колдун","Чародей"],"ds":"Буря (духов) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Мудрость): 3к6 урона (психический) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Буря","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-sfera-mirazhey","n":"Сфера Миражей","l":2,"sc":"Иллюзия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Колдун","Бард","Волшебник"],"ds":"Сфера (миражей) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Интеллект): 2к6 урона (психический) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Сфера","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-apokalipsis-sveta","n":"Апокалипсис Света","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 излучение","cl":["Жрец","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Телосложение): 14к6 урона (излучение) плюс 14к6 силовым полем при провале (и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Телосложение","atk":false,"mech":"Апокалипсис","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-vrata-shipov","n":"Врата Шипов","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 колющий","cl":["Следопыт","Чародей","Друид"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (шипов). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (колющий). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-zavesa-run","n":"Завеса Рун","l":2,"sc":"Ограждение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Жрец","Следопыт","Волшебник"],"ds":"Куб с ребром 6 м заполняется завесой (рун): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Интеллект) — при провале оно получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Завеса","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-kasanie-vremeni","n":"Касание Времени","l":0,"sc":"Преобразование","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (силовое поле), и цель замедляется: не может совершать бонусных действий до конца своего следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-tropa-teni","n":"Тропа Тени","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Клочок чёрной ткани.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Изобретатель"],"ds":"До 8 согласных существ отправляются в путь сквозь тени: группа шагает в одну тень и выходит из другой. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-morok-krovi","n":"Морок Крови","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Жрец"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также не может восстанавливать хиты до конца своего следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-otmetina-molniy","n":"Отметина Молний","l":0,"sc":"Воплощение","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 электричество","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Вы отмечаете существо знаком (молний). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (электричество). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-kara-groma","n":"Кара Грома","l":5,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 звук","cl":["Чародей","Бард","Жрец"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (звук) при провале (и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-strazh-ineya","n":"Страж Инея","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 холод","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (инея): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (холод)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-obereg-plameni","n":"Оберег Пламени","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «огонь», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-legion-kostey","n":"Легион Костей","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Появляются четыре духа (костей): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «колющий». Каждый атакует заклинанием 1,5 м на 2к6 урона (колющий). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-pechat-pustoty","n":"Печать Пустоты","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Чёрная жемчужина.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 силовое поле","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Харизма): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Харизма","atk":false,"mech":"Печать","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-kope-zvezd","n":"Копьё Звёзд","l":1,"sc":"Прорицание","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 излучение","cl":["Бард","Жрец","Друид"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (излучение). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-dvoynik-razuma","n":"Двойник Разума","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 психический","cl":["Бард","Колдун","Паладин"],"ds":"Вы создаёте двойника из отвердевшей мысли — предмет повинуется простым мысленным командам. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (психический) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-potok-yada","n":"Поток Яда","l":3,"sc":"Преобразование","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Телосложение): 7к6 урона (яд) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Поток","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-uzy-voln","n":"Узы Волн","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 дробящий","cl":["Чародей","Жрец","Следопыт"],"ds":"Узы (волн) охватывают существо: спасбросок (Сила) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (дробящий) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Узы","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-raspad-vetra","n":"Распад Ветра","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Перо.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 звук","cl":["Чародей","Друид"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (звук) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-duh-kamnya","n":"Дух Камня","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 дробящий","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы призываете духа (камня) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (дробящий). Иммунитет к урону «дробящий». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-kleymo-duhov","n":"Клеймо Духов","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (психический), и цель совершает спасбросок (Мудрость) — при провале она испугана вами до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Клеймо","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-avatar-mirazhey","n":"Аватар Миражей","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 психический","cl":["Бард","Колдун"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «психический», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (психический). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-aura-sveta","n":"Аура Света","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Паладин","Жрец","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «излучение» и преимущество на спасброски от эффектов, из-за которых цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Телосложение) или получает 2к6 урона (излучение). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Аура","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-golos-shipov","n":"Голос Шипов","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (шипов). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-carstvo-run","n":"Царство Рун","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Резец и кусочек кости.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (рун) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Интеллект","atk":false,"mech":"Царство","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-perenos-vremeni","n":"Перенос Времени","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Бард","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь «сквозь мгновение» на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-balzam-teni","n":"Бальзам Тени","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «некротика» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-slovo-krovi","n":"Слово Крови","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 некротика","cl":["Чародей","Жрец"],"ds":"Вы произносите истинное слово (крови). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (некротика) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-oblik-molniy","n":"Облик Молний","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 электричество","cl":["Изобретатель","Волшебник","Друид"],"ds":"Вы принимаете облик (молний): сопротивление урону «электричество» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (электричество). Попадание: цель не может совершать реакции до начала своего следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-cep-groma","n":"Цепь Грома","l":2,"sc":"Воплощение","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 звук","cl":["Чародей","Бард","Жрец"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (звук) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-iskra-ineya","n":"Искра Инея","l":0,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 холод","cl":["Чародей","Волшебник","Друид"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (холод). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-stena-plameni","n":"Стена Пламени","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 огонь","cl":["Чародей","Колдун","Паладин"],"ds":"Стена (пламени) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Ловкость): 5к8 урона (огонь) при провале (и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Ловкость","atk":false,"mech":"Стена","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-zavesa-kostey","n":"Завеса Костей","l":2,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Куб с ребром 6 м заполняется завесой (костей): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Телосложение) — при провале оно становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Завеса","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-kasanie-pustoty","n":"Касание Пустоты","l":0,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (силовое поле), и цель не может телепортироваться и перемещаться между планами до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-tropa-zvezd","n":"Тропа Звёзд","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Жрец","Паладин"],"ds":"До 8 согласных существ отправляются в путь по звёздной карте: группа никогда не сбивается с пути и движется вдвое быстрее. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-morok-razuma","n":"Морок Разума","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Чародей","Колдун"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также не может совершать реакции и совершает с помехой следующую проверку Интеллекта. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-otmetina-yada","n":"Отметина Яда","l":0,"sc":"Преобразование","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 яд","cl":["Следопыт","Изобретатель","Паладин"],"ds":"Вы отмечаете существо знаком (яда). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (яд). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-kara-voln","n":"Кара Волн","l":5,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Одно существо совершает спасбросок (Сила): 8к8 урона (дробящий) при провале (и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Сила","atk":false,"mech":"Кара","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-strazh-vetra","n":"Страж Ветра","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 звук","cl":["Следопыт","Друид","Колдун"],"ds":"Вы призываете крошечного духа (ветра): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (звук)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-obereg-kamnya","n":"Оберег Камня","l":0,"sc":"Преобразование","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «дробящий», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-svyatilische-duhov","n":"Святилище Духов","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Благовония.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Мудрость) — при провале они испугана вами до конца её следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Мудрость","atk":false,"mech":"Святилище","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-vzryv-mirazhey","n":"Взрыв Миражей","l":3,"sc":"Иллюзия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек стекла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 психический","cl":["Бард","Колдун","Чародей"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Интеллект), получая 6к6 урона (психический) при провале (и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Взрыв","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-volna-sveta","n":"Волна Света","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 излучение","cl":["Жрец","Друид","Бард"],"ds":"Существа в конусе совершают спасбросок (Телосложение): при провале 2к6 урона (излучение) и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Волна","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-svyaz-shipov","n":"Связь Шипов","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Бард"],"ds":"Вы вопрошаете ближайшее растение (оно помнит, кто проходил мимо за неделю), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-kokon-run","n":"Кокон Рун","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Следопыт"],"ds":"Кокон (рун) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Интеллект) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Кокон","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-pokrov-vremeni","n":"Покров Времени","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Песчинка из песочных часов.","d":"1 час","conc":false,"rit":false,"dmg":"5 силовое поле","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (силовое поле); у вас сопротивление урону «силовое поле». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-kolco-teni","n":"Кольцо Тени","l":6,"sc":"Иллюзия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 некротика","cl":["Колдун","Чародей"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Мудрость): при провале оно получает 6к8 урона (некротика), не проходит и окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Мудрость","atk":false,"mech":"Кольцо","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-ubezhische-krovi","n":"Убежище Крови","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Капля вашей крови.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: стены из багровой корки, внутри раны не воспаляются и восстанавливается +1 Кость Хитов. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-chute-molniy","n":"Чутьё Молний","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Друид","Изобретатель","Бард"],"ds":"Вы чувствуете металл, механизмы и существ с иммунитетом к электричеству в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-katastrofa-groma","n":"Катастрофа Грома","l":7,"sc":"Воплощение","t":"1 действие","r":"300 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 звук","cl":["Бард","Чародей"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Телосложение) — 12к6 урона (звук) при провале (и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Телосложение","atk":false,"mech":"Катастрофа","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-opros-ineya","n":"Опрос Инея","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Волшебник","Друид","Изобретатель"],"ds":"Вы обращаетесь к стихии: вопрошаете лёд или снег поблизости (он помнит следы и голоса за последнюю неделю). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-shag-plameni","n":"Шаг Пламени","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 огонь","cl":["Колдун","Изобретатель","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Ловкость) или получает 1к6 урона (огонь). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Шаг","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-carstvo-kostey","n":"Царство Костей","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Фаланга пальца.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Колдун"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (костей) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-perenos-pustoty","n":"Перенос Пустоты","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Волшебник","Паладин"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь сквозь пустоту на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-balzam-zvezd","n":"Бальзам Звёзд","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «излучение» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-slovo-razuma","n":"Слово Разума","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 психический","cl":["Чародей","Бард"],"ds":"Вы произносите истинное слово (разума). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (психический) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-oblik-yada","n":"Облик Яда","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 яд","cl":["Следопыт","Изобретатель","Колдун"],"ds":"Вы принимаете облик (яда): сопротивление урону «яд» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (яд). Попадание: цель отравлена до конца своего следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-cep-voln","n":"Цепь Волн","l":2,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (дробящий) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Сила) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Сила","atk":true,"mech":"Цепь","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-iskra-vetra","n":"Искра Ветра","l":0,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 звук","cl":["Чародей","Друид","Изобретатель"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (звук). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-stena-kamnya","n":"Стена Камня","l":4,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 дробящий","cl":["Друид","Волшебник","Чародей"],"ds":"Стена (камня) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Сила): 5к8 урона (дробящий) при провале (и цель сбивается с ног, если она Большая или меньше), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Стена","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-oruzhie-duhov","n":"Оружие Духов","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 психический","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (психический). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Мудрость): при провале она испугана вами до конца её следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-vspyshka-mirazhey","n":"Вспышка Миражей","l":0,"sc":"Иллюзия","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Интеллект), получая 1к6 урона (психический) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Интеллект","atk":false,"mech":"Вспышка","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-proklyatie-sveta","n":"Проклятие Света","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Паладин","Жрец","Чародей"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (излучение), а в начале каждого её хода она бросает к4: на 1 она излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-slepok-shipov","n":"Слепок Шипов","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы создаёте немагический предмет из живого дерева, продолжающего расти размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-maloe-chudo-run","n":"Малое Чудо Рун","l":0,"sc":"Ограждение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Изобретатель","Волшебник"],"ds":"Вы творите мелкое чудо: начертать светящуюся руну, видимую только выбранным существам, или прочесть одну незнакомую надпись. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-legion-vremeni","n":"Легион Времени","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Следопыт","Волшебник","Друид"],"ds":"Появляются четыре духа (времени): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «силовое поле». Каждый атакует заклинанием 1,5 м на 2к6 урона (силовое поле). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-pechat-teni","n":"Печать Тени","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Клочок чёрной ткани.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 некротика","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Мудрость): 3к6 урона (некротика) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Печать","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-kope-krovi","n":"Копьё Крови","l":1,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (некротика). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-dvoynik-molniy","n":"Двойник Молний","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 электричество","cl":["Изобретатель","Бард","Друид"],"ds":"Вы создаёте двойника из медной проволоки, гудящей от заряда. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (электричество) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-potok-groma","n":"Поток Грома","l":3,"sc":"Воплощение","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 звук","cl":["Чародей","Бард","Жрец"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Телосложение): 7к6 урона (звук) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Поток","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-uzy-ineya","n":"Узы Инея","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 холод","cl":["Чародей","Следопыт","Друид"],"ds":"Узы (инея) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (холод) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-raspad-plameni","n":"Распад Пламени","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть серы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 огонь","cl":["Чародей","Колдун"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (огонь) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-kokon-kostey","n":"Кокон Костей","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Колдун","Жрец","Паладин"],"ds":"Кокон (костей) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-pokrov-pustoty","n":"Покров Пустоты","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Чёрная жемчужина.","d":"1 час","conc":false,"rit":false,"dmg":"5 силовое поле","cl":["Волшебник","Паладин","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (силовое поле); у вас сопротивление урону «силовое поле». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-kolco-zvezd","n":"Кольцо Звёзд","l":6,"sc":"Прорицание","t":"1 действие","r":"45 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 излучение","cl":["Бард","Жрец"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Мудрость): при провале оно получает 6к8 урона (излучение), не проходит и очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Мудрость","atk":false,"mech":"Кольцо","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-ubezhische-razuma","n":"Убежище Разума","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: мысленный купол: внутри невозможно прочитать мысли или подслушать. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-chute-yada","n":"Чутьё Яда","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Изобретатель"],"ds":"Вы чувствуете яды, болезни и ядовитых существ в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-katastrofa-voln","n":"Катастрофа Волн","l":7,"sc":"Вызов","t":"1 действие","r":"300 м","c":"ВСМ","m":"Морская ракушка.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 дробящий","cl":["Чародей","Жрец"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Сила) — 12к6 урона (дробящий) при провале (и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Сила","atk":false,"mech":"Катастрофа","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-opros-vetra","n":"Опрос Ветра","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Перо.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы обращаетесь к стихии: вопрошаете ветер (он приносит слова, сказанные здесь за последние сутки). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-shag-kamnya","n":"Шаг Камня","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 дробящий","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Сила) или получает 1к6 урона (дробящий). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Шаг","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-vlast-duhov","n":"Власть Духов","l":8,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 психический","cl":["Бард","Жрец"],"ds":"Вы повелеваете стихией (духов) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Мудрость), 6к10 урона (психический) при провале и цель испугана вами до конца её следующего хода, половина при успехе.","save":"Мудрость","atk":false,"mech":"Власть","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-burya-mirazhey","n":"Буря Миражей","l":4,"sc":"Иллюзия","t":"1 действие","r":"90 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 психический","cl":["Бард","Колдун","Чародей"],"ds":"Буря (миражей) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Интеллект): 3к6 урона (психический) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Интеллект","atk":false,"mech":"Буря","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-sfera-sveta","n":"Сфера Света","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Жрец","Чародей","Друид"],"ds":"Сфера (света) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (излучение) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-apokalipsis-shipov","n":"Апокалипсис Шипов","l":9,"sc":"Преобразование","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 колющий","cl":["Друид","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Сила): 14к6 урона (колющий) плюс 14к6 силовым полем при провале (и цель опутывается колючими лозами: скорость 0 до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Сила","atk":false,"mech":"Апокалипсис","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-vrata-run","n":"Врата Рун","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 силовое поле","cl":["Жрец","Чародей","Паладин"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (рун). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (силовое поле). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-zavesa-vremeni","n":"Завеса Времени","l":2,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Бард","Следопыт","Волшебник"],"ds":"Куб с ребром 6 м заполняется завесой (времени): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Мудрость) — при провале оно замедляется: не может совершать бонусных действий до конца своего следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Завеса","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-kasanie-teni","n":"Касание Тени","l":0,"sc":"Иллюзия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 некротика","cl":["Колдун","Волшебник","Изобретатель"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (некротика), и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-tropa-krovi","n":"Тропа Крови","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Капля вашей крови.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Следопыт"],"ds":"До 8 согласных существ отправляются в путь по кровной связи: группа переносится к кровному родственнику одного из участников. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-morok-molniy","n":"Морок Молний","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Друид","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также не может совершать реакции до начала своего следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-otmetina-groma","n":"Отметина Грома","l":0,"sc":"Воплощение","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 звук","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (грома). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (звук). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-kara-ineya","n":"Кара Инея","l":5,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 холод","cl":["Чародей","Изобретатель","Друид"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (холод) при провале (и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Инея","orig":true,"pack":"spells10.js"},{"id":"sp10-strazh-plameni","n":"Страж Пламени","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 огонь","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (пламени): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (огонь)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Пламени","orig":true,"pack":"spells10.js"},{"id":"sp10-maloe-chudo-kostey","n":"Малое Чудо Костей","l":0,"sc":"Некромантия","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Колдун","Волшебник"],"ds":"Вы творите мелкое чудо: заставить скелет или череп двигать челюстью или узнать возраст костей. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Костей","orig":true,"pack":"spells10.js"},{"id":"sp10-legion-pustoty","n":"Легион Пустоты","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Колдун","Волшебник","Следопыт"],"ds":"Появляются четыре духа (пустоты): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «силовое поле». Каждый атакует заклинанием 1,5 м на 2к6 урона (силовое поле). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Пустоты","orig":true,"pack":"spells10.js"},{"id":"sp10-pechat-zvezd","n":"Печать Звёзд","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 излучение","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Мудрость): 3к6 урона (излучение) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Печать","theme":"Звёзд","orig":true,"pack":"spells10.js"},{"id":"sp10-kope-razuma","n":"Копьё Разума","l":1,"sc":"Очарование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 психический","cl":["Бард","Чародей","Колдун"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (психический). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Разума","orig":true,"pack":"spells10.js"},{"id":"sp10-dvoynik-yada","n":"Двойник Яда","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 яд","cl":["Следопыт","Изобретатель","Колдун"],"ds":"Вы создаёте двойника из ядовитого хитина (касание без перчаток — 1 урон ядом). Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (яд) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Яда","orig":true,"pack":"spells10.js"},{"id":"sp10-potok-voln","n":"Поток Волн","l":3,"sc":"Вызов","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Сила): 7к6 урона (дробящий) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Поток","theme":"Волн","orig":true,"pack":"spells10.js"},{"id":"sp10-uzy-vetra","n":"Узы Ветра","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 звук","cl":["Следопыт","Чародей","Друид"],"ds":"Узы (ветра) охватывают существо: спасбросок (Сила) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (звук) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Узы","theme":"Ветра","orig":true,"pack":"spells10.js"},{"id":"sp10-raspad-kamnya","n":"Распад Камня","l":6,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек гранита.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 дробящий","cl":["Чародей","Волшебник"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (дробящий) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Камня","orig":true,"pack":"spells10.js"},{"id":"sp10-duh-duhov","n":"Дух Духов","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 психический","cl":["Колдун","Жрец","Друид"],"ds":"Вы призываете духа (духов) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (психический). Иммунитет к урону «психический». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Духов","orig":true,"pack":"spells10.js"},{"id":"sp10-kleymo-mirazhey","n":"Клеймо Миражей","l":1,"sc":"Иллюзия","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (психический), и цель совершает спасбросок (Интеллект) — при провале она видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Клеймо","theme":"Миражей","orig":true,"pack":"spells10.js"},{"id":"sp10-avatar-sveta","n":"Аватар Света","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 излучение","cl":["Жрец","Чародей"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «излучение», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (излучение). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Света","orig":true,"pack":"spells10.js"},{"id":"sp10-aura-shipov","n":"Аура Шипов","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Следопыт","Друид","Паладин"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «колющий» и преимущество на спасброски от эффектов, из-за которых цель опутывается колючими лозами. Враг, начинающий ход в ауре, совершает спасбросок (Сила) или получает 2к6 урона (колющий). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Аура","theme":"Шипов","orig":true,"pack":"spells10.js"},{"id":"sp10-golos-run","n":"Голос Рун","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Чародей","Бард"],"ds":"Ваш голос наполняется силой стихии (рун). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Рун","orig":true,"pack":"spells10.js"},{"id":"sp10-carstvo-vremeni","n":"Царство Времени","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Песчинка из песочных часов.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Бард","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (времени) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Мудрость","atk":false,"mech":"Царство","theme":"Времени","orig":true,"pack":"spells10.js"},{"id":"sp10-perenos-teni","n":"Перенос Тени","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь сквозь тени на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Тени","orig":true,"pack":"spells10.js"},{"id":"sp10-balzam-krovi","n":"Бальзам Крови","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Следопыт","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «некротика» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Крови","orig":true,"pack":"spells10.js"},{"id":"sp10-slovo-molniy","n":"Слово Молний","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 электричество","cl":["Чародей","Бард"],"ds":"Вы произносите истинное слово (молний). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (электричество) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Молний","orig":true,"pack":"spells10.js"},{"id":"sp10-oblik-groma","n":"Облик Грома","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 звук","cl":["Бард","Жрец","Паладин"],"ds":"Вы принимаете облик (грома): сопротивление урону «звук» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (звук). Попадание: цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Грома","orig":true,"pack":"spells10.js"},{"id":"sp10-cep-ineya","n":"Цепь Инея","l":2,"sc":"Воплощение","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 холод","cl":["Чародей","Друид","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (холод) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Инея","orig":true,"pack":"spells10.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
